cd agents/hermes-agent && python3 -c "
from pathlib import Path
from tools.registry import _module_registers_tools
tools_path = Path('tools')

for path in sorted(tools_path.glob('*.py')):
    if path.name not in {'__init__.py', 'registry.py', 'mcp_tool.py'}:
        has_register = _module_registers_tools(path)
        if has_register:
            print(f'✓ {path.name} - will be auto-discovered')
        elif 'forget' in path.name.lower():
            print(f'✗ {path.name} - NOT registered (no registry.register found)')
"
